// Generates the complete 15s score for the film from scratch.
// Everything here is math: pad, room tone, servo whirs, gripper, ceramic
// contact, sub swell and shimmer. No samples, no downloads.
//
//   node tools/make-score.mjs
//
import fs from "node:fs";
import { execFileSync } from "node:child_process";

const SR = 48000;
const DUR = 15.0;
const N = Math.round(SR * DUR);
const TAU = Math.PI * 2;

const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
const lerp = (a, b, t) => a + (b - a) * t;
const smooth = (a, b, x) => {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};

function mulberry32(a) {
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
